buildGroundAO:
function buildGroundAO() {
  const R = 1024, cell = WSIZE / R, b = new Uint8Array(R * R);
  const put = (x0, z0, rr, fn) => {
    const i0 = Math.max(0, Math.floor((x0 - rr + HALF) / cell)), i1 = Math.min(R - 1, Math.ceil((x0 + rr + HALF) / cell));
    const j0 = Math.max(0, Math.floor((z0 - rr + HALF) / cell)), j1 = Math.min(R - 1, Math.ceil((z0 + rr + HALF) / cell));
    for (let j = j0; j <= j1; j++) for (let i = i0; i <= i1; i++) {
      const v = fn(-HALF + (i + 0.5) * cell, -HALF + (j + 0.5) * cell);
      if (v > 0) { const q = j * R + i; b[q] = Math.max(b[q], Math.round(clamp(v, 0, 1) * 255)); }
    }
  };
  for (const c of COLL.boxes) {
    if (!['wall', 'house', 'gate', 'stone', 'fence', 'prop'].includes(c.tag)) continue;
    const reach = clamp((c.h || 3) * 0.32, 0.7, 2.6), k = clamp((c.h || 3) / 3, 0.35, 1);
    put(c.x, c.z, Math.hypot(c.hx, c.hz) + reach, (x, z) => {
      const dx = x - c.x, dz = z - c.z;
      const lx = Math.abs(dx * c.cos - dz * c.sin) - c.hx, lz = Math.abs(dx * c.sin + dz * c.cos) - c.hz;
      const d = Math.hypot(Math.max(lx, 0), Math.max(lz, 0));
      const f = 1 - d / reach;
      return f > 0 ? k * f * f : 0;
    });
  }
  for (const c of COLL.circles) {
    if (c.tag === 'tree') continue;
    const reach = clamp((c.h || 2) * 0.3, 0.5, 1.6), k = clamp((c.h || 2) / 3, 0.3, 0.8);
    put(c.x, c.z, c.r + reach, (x, z) => { const f = 1 - Math.max(0, Math.hypot(x - c.x, z - c.z) - c.r) / reach; return f > 0 ? k * f * f : 0; });
  }
  // [look2] and in its second channel the towns' footpaths at 1 m (13u_look2.js: groundPath, 02_render.js)
  const rg = new Uint8Array(R * R * 2);
  for (let q = 0; q < R * R; q++) rg[q * 2] = b[q];
  look2PathMap(rg, R);
  look3PathMap(rg, R); // [look3] the keeps' halls' paths (13v_look3.js)
  const tex = new THREE.DataTexture(rg, R, R, THREE.RGFormat, THREE.UnsignedByteType);
  tex.minFilter = THREE.LinearFilter; tex.magFilter = THREE.LinearFilter; tex.generateMipmaps = false;
  tex.needsUpdate = true;
  U.uGroundAO.value = tex;
  CANOPY.ao = b;
}

util:
const clamp = (x, a, b) => (x < a ? a : x > b ? b : x);
const smooth = (t) => t * t * (3 - 2 * t);
const sstep = (e0, e1, x) => { const t = clamp((x - e0) / (e1 - e0), 0, 1); return t * t * (3 - 2 * t); };
const dist2 = (ax, az, bx, bz) => { const dx = ax - bx, dz = az - bz; return dx * dx + dz * dz; };
function segDist2(px, pz, ax, az, bx, bz) {
  const abx = bx - ax, abz = bz - az;
  const l2 = abx * abx + abz * abz;
  let t = l2 > 1e-9 ? ((px - ax) * abx + (pz - az) * abz) / l2 : 0;
  t = clamp(t, 0, 1);
  const qx = ax + abx * t, qz = az + abz * t;
  return dist2(px, pz, qx, qz);
}

town:
function lookTownPlan() {
  if (LOOK.towns.length) return LOOK.towns;
  for (const R of REALMS) {
    const S = R.town, T = { S, realm: R.id, r0: 35, r1: 44, paths: [], houses: [] };
    for (const H of HOUSES) {
      if (H.keepHall || H.S !== S) continue;
      T.houses.push(H);
      const D = H.door, o = D.out, dx = S.x - o.x, dz = S.z - o.z, d = Math.hypot(dx, dz) || 1;
      // from the doorstep straight out to the plaza's edge (the doors face the plaza)
      const end = Math.max(0, d - 12.5);
      T.paths.push({ ax: D.c.x, az: D.c.z, bx: o.x + dx / d * end, bz: o.z + dz / d * end, w: H.big ? 1.9 : 1.5, house: H.num });
    }
    LOOK.towns.push(T);
  }
  return LOOK.towns;
}
const lookSegD = (x, z, P) => Math.sqrt(segDist2(x, z, P.ax, P.az, P.bx, P.bz));

hall:
function look3HallPlan() {
  if (LOOK3.halls) return LOOK3.halls;
  if (typeof HALL === 'undefined' || !HALL.list.length) return [];
  const out = [];
  for (const H of HALL.list) {
    const S = H.S, D = H.door;
    if (!S || !D || !D.c || !S.gateLocal) continue;
    // to just inside the gate: the courtyard's side of the gateway (the wall's thickness and a step beyond)
    const R = REALMS[H.realm] || REALMS[0], round = R.style === 'round';
    const gz = S.gateLocal.z - (round ? KEEP_T + 1.2 : KEEP_T + 1.4), g = siteToWorld(S, S.gateLocal.x, gz);
    out.push({ ax: D.c.x, az: D.c.z, bx: g.x, bz: g.z, w: 1.9, S, H });
  }
  return (LOOK3.halls = out);
}

paths:
function look2PathMap(rg, R) {
  if (typeof lookTownPlan !== 'function' || !HOUSES.length) return; // (the plan is kept once made: never before the houses)
  for (const T of lookTownPlan()) for (const P of T.paths) {
    const hw = P.w / 2, pad = hw + 1.2;
    const x0 = Math.min(P.ax, P.bx) - pad, x1 = Math.max(P.ax, P.bx) + pad, z0 = Math.min(P.az, P.bz) - pad, z1 = Math.max(P.az, P.bz) + pad;
    for (let j = Math.max(0, Math.floor(z0 + 512)); j <= Math.min(R - 1, Math.ceil(z1 + 512)); j++) {
      for (let i = Math.max(0, Math.floor(x0 + 512)); i <= Math.min(R - 1, Math.ceil(x1 + 512)); i++) {
        const x = i - 512 + 0.5, z = j - 512 + 0.5, pd = lookSegD(x, z, P);
        // full across the path, falling off over a metre beyond its edge (the shader sharpens it again)
        const v = Math.round(255 * sstep(hw + 0.9, hw - 0.35, pd));
        const q = (j * R + i) * 2 + 1;
        if (v > rg[q]) rg[q] = v;
      }
    }
  }
}
function look3PathMap(rg, R) {
  for (const P of look3HallPlan()) {
    const hw = P.w / 2, pad = hw + 1.2;
    const x0 = Math.min(P.ax, P.bx) - pad, x1 = Math.max(P.ax, P.bx) + pad, z0 = Math.min(P.az, P.bz) - pad, z1 = Math.max(P.az, P.bz) + pad;
    for (let j = Math.max(0, Math.floor(z0 + 512)); j <= Math.min(R - 1, Math.ceil(z1 + 512)); j++) {
      for (let i = Math.max(0, Math.floor(x0 + 512)); i <= Math.min(R - 1, Math.ceil(x1 + 512)); i++) {
        const x = i - 512 + 0.5, z = j - 512 + 0.5, pd = lookSegD(x, z, P);
        const v = Math.round(255 * sstep(hw + 0.9, hw - 0.35, pd));
        const q = (j * R + i) * 2 + 1;
        if (v > rg[q]) rg[q] = v;
      }
    }
  }
}
